namespace Aster {
static partial class Inventory {
 static string Property(ManagementBaseObject o,string key){try{return S(o[key]);}catch{return "Unavailable";}}
 static string FormatSpec(string key,string value){double n;if(!double.TryParse(value,out n))return value;
  if(key=="Capacity"||key=="Size")return Bytes(n);
  if(key=="MaxClockSpeed"||key=="CurrentClockSpeed")return n+" MHz (firmware reported)";
  if(key=="ConfiguredClockSpeed"||key=="Speed")return n+" (Windows memory speed value)";
  if(key=="L2CacheSize"||key=="L3CacheSize")return n+" KB";
  if(key=="SMBIOSMemoryType"){var m=new Dictionary<int,string>{{20,"DDR"},{21,"DDR2"},{24,"DDR3"},{26,"DDR4"},{30,"LPDDR4"},{34,"DDR5"},{35,"LPDDR5"}};return m.ContainsKey((int)n)?m[(int)n]:n+" (SMBIOS type code)";}
  if(key=="FormFactor"){if(n==8)return "DIMM";if(n==12)return "SO-DIMM";return n+" (form factor code)";}
  return value;
 }
 static void Specs(Table t,string component,string wmiClass,string[] fields,string scope=null){try{using(var q=scope==null?new ManagementObjectSearcher("SELECT * FROM "+wmiClass):new ManagementObjectSearcher(scope,"SELECT * FROM "+wmiClass)){q.Options.Timeout=TimeSpan.FromSeconds(10);int index=0;foreach(ManagementObject o in q.Get()){using(o){string group=component+" "+index++;foreach(var field in fields){var parts=field.Split('|');t.Rows.Add(new[]{group,parts.Length>1?parts[1]:parts[0],FormatSpec(parts[0],Property(o,parts[0]))});}}}if(index==0)t.Rows.Add(new[]{component,"Status","No entries reported"});}}catch(Exception ex){t.Rows.Add(new[]{component,"Provider unavailable",ex.Message});}}
 public static Table Hardware(string name){var t=new Table("Component","Specification","Value");switch(name){
 case "CPU specs":Specs(t,"CPU","Win32_Processor",new[]{"Name|Model","Manufacturer","SocketDesignation|Socket","NumberOfCores|Physical cores","NumberOfEnabledCore|Enabled cores","NumberOfLogicalProcessors|Logical processors","MaxClockSpeed|Maximum firmware clock","CurrentClockSpeed|Current firmware clock","L2CacheSize|L2 cache","L3CacheSize|L3 cache","AddressWidth|Address width (bits)","VirtualizationFirmwareEnabled|Virtualization enabled in firmware","SecondLevelAddressTranslationExtensions|Second-level address translation","ProcessorId|Processor identifier"});t.Note="Firmware clock values are not a live boost-clock sensor. Live CPU load is on Summary / Performance.";break;
 case "Memory specs":Specs(t,"Memory module","Win32_PhysicalMemory",new[]{"DeviceLocator|Slot","BankLabel|Bank","Manufacturer","PartNumber|Part number","Capacity","SMBIOSMemoryType|Memory type","FormFactor|Form factor","Speed|Rated speed","ConfiguredClockSpeed|Configured speed","DataWidth|Data width (bits)","TotalWidth|Total width (bits)"});Specs(t,"Memory array","Win32_PhysicalMemoryArray",new[]{"MemoryDevices|Slots reported","MaxCapacityEx|Maximum supported capacity (KB)","MemoryErrorCorrection|Error correction (SMBIOS code)"});t.Note="Capacity and module details from firmware. Live RAM usage appears on Summary / Performance.";break;
 case "Storage specs":Specs(t,"Disk","Win32_DiskDrive",new[]{"Index|Disk index","Model","FirmwareRevision|Firmware","SerialNumber|Serial number","Size|Capacity","InterfaceType|Legacy interface label","MediaType|Legacy media label","Partitions|Partition count","BytesPerSector|Bytes per sector","PNPDeviceID|Device identifier"});Specs(t,"Storage device","MSFT_PhysicalDisk",new[]{"DeviceId|Device ID","FriendlyName|Model","MediaType|Media type code (3 HDD / 4 SSD / 5 SCM)","BusType|Bus code (7 USB / 11 SATA / 17 NVMe)","Size|Capacity","HealthStatus|Health code (0 healthy / 1 warning / 2 unhealthy)","SpindleSpeed|Spindle speed (RPM)"},@"root\Microsoft\Windows\Storage");t.Note="Modern storage provider may require additional Windows access. Disk space lists mounted volumes separately.";break;
 case "Motherboard & BIOS":Specs(t,"Motherboard","Win32_BaseBoard",new[]{"Manufacturer","Product|Model","Version","SerialNumber|Serial number"});Specs(t,"BIOS","Win32_BIOS",new[]{"Manufacturer","SMBIOSBIOSVersion|BIOS version","ReleaseDate|Release date (WMI format)","SMBIOSMajorVersion|SMBIOS major version","SMBIOSMinorVersion|SMBIOS minor version"});Specs(t,"System","Win32_ComputerSystem",new[]{"Manufacturer","Model","SystemType|Architecture","NumberOfProcessors|CPU sockets","HypervisorPresent|Hypervisor present"});break;
 case "GPU":Specs(t,"Graphics adapter","Win32_VideoController",new[]{"Name|Model","AdapterCompatibility|Vendor","VideoProcessor|Video processor","DriverVersion|Driver version","DriverDate|Driver date (WMI format)","PNPDeviceID|Device identifier","CurrentHorizontalResolution|Horizontal pixels","CurrentVerticalResolution|Vertical pixels","CurrentRefreshRate|Refresh rate (Hz)","VideoModeDescription|Display mode"});t.Note="NVIDIA telemetry refreshes every five cycles; other adapters show Windows-reported specifications.";break;
 case "Network adapters":try{foreach(var n in NetworkInterface.GetAllNetworkInterfaces()){string group=n.Name;t.Rows.Add(new[]{group,"Description",n.Description});t.Rows.Add(new[]{group,"Type",n.NetworkInterfaceType.ToString()});t.Rows.Add(new[]{group,"Status",n.OperationalStatus.ToString()});t.Rows.Add(new[]{group,"Link speed",(n.Speed/1000000.0).ToString("F0")+" Mbps"});t.Rows.Add(new[]{group,"MAC address",n.GetPhysicalAddress().ToString()});try{var p=n.GetIPProperties();t.Rows.Add(new[]{group,"IP addresses",string.Join(", ",p.UnicastAddresses.Select(a=>a.Address.ToString()))});t.Rows.Add(new[]{group,"Gateways",string.Join(", ",p.GatewayAddresses.Select(a=>a.Address.ToString()))});t.Rows.Add(new[]{group,"DNS servers",string.Join(", ",p.DnsAddresses.Select(a=>a.ToString()))});}catch{t.Rows.Add(new[]{group,"Address details","Unavailable"});}}}catch(Exception ex){t.Rows.Add(new[]{"Network","Provider unavailable",ex.Message});}t.Note="Includes physical and virtual adapters. Link speed is negotiated capacity, not internet speed.";break;
 }return t;}
}
class GpuSensor {public string Index,Name,Driver;public double Total,Used,Load,Temp,Power,Limit,Clock;}
static class Nvidia {
 public static double Number(string text){double n;return double.TryParse(text.Trim(),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out n)?n:double.NaN;}
 public static List<GpuSensor> Parse(string output){var rows=new List<GpuSensor>();foreach(var line in output.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){var x=line.Split(',').Select(v=>v.Trim()).ToArray();if(x.Length!=10)continue;rows.Add(new GpuSensor{Index=x[0],Name=x[1],Total=Number(x[2]),Used=Number(x[3]),Load=Number(x[4]),Temp=Number(x[5]),Power=Number(x[6]),Limit=Number(x[7]),Clock=Number(x[8]),Driver=x[9]});}return rows;}
 public static List<GpuSensor> Read(){string exe=new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),@"System32\nvidia-smi.exe"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),@"NVIDIA Corporation\NVSMI\nvidia-smi.exe")}.FirstOrDefault(File.Exists);if(exe==null)return new List<GpuSensor>();try{using(var p=new Process()){p.StartInfo=new ProcessStartInfo(exe,"--query-gpu=index,name,memory.total,memory.used,utilization.gpu,temperature.gpu,power.draw,power.limit,clocks.current.graphics,driver_version --format=csv,noheader,nounits"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};p.Start();var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(3500)){try{p.Kill();}catch{}return new List<GpuSensor>();}if(p.ExitCode!=0)return new List<GpuSensor>();return Parse(output.GetAwaiter().GetResult());}}catch{return new List<GpuSensor>();}}
}
partial class MainWindow {
 Graph summaryCpu,summaryRam;DataGridView topProcesses;Label liveOverview,liveHardware,sensorStrip;List<GpuSensor> sensors=new List<GpuSensor>();DateTime sensorTime;string storageOverview="Storage: reading device inventory…";
 static string Metric(double n,string unit){return double.IsNaN(n)?"Unavailable":n.ToString("F1")+unit;}
 void BuildLegacySummary(){var wrap=new Panel{Dock=DockStyle.Fill,AutoScroll=true};var table=new TableLayoutPanel{Dock=DockStyle.Top,Height=660,ColumnCount=2,RowCount=4};table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,55));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,45));table.RowStyles.Add(new RowStyle(SizeType.Absolute,88));table.RowStyles.Add(new RowStyle(SizeType.Absolute,245));table.RowStyles.Add(new RowStyle(SizeType.Absolute,225));table.RowStyles.Add(new RowStyle(SizeType.Absolute,102));wrap.Controls.Add(table);content.Controls.Add(wrap);
 liveOverview=new Label{Dock=DockStyle.Fill,BackColor=panel,ForeColor=cyan,Font=new Font("Segoe UI",12),Padding=new Padding(14),Margin=new Padding(0,0,0,12),Text="Waiting for live samples…"};table.Controls.Add(liveOverview,0,0);table.SetColumnSpan(liveOverview,2);
 summaryCpu=NewGraph("CPU",cyan,false);summaryRam=NewGraph("MEMORY",Color.FromArgb(188,133,245),false);table.Controls.Add(summaryCpu,0,1);table.Controls.Add(summaryRam,1,1);foreach(var s in history){summaryCpu.Add(s.Cpu);summaryRam.Add(s.MemoryPercent);}
 var box=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1,Margin=new Padding(0,0,14,12)};box.RowStyles.Add(new RowStyle(SizeType.Absolute,28));box.RowStyles.Add(new RowStyle(SizeType.Percent,100));box.Controls.Add(new Label{Text="BUSIEST PROCESSES · CPU",Dock=DockStyle.Fill,ForeColor=muted},0,0);topProcesses=MakeGrid();topProcesses.ColumnHeadersHeight=30;topProcesses.RowTemplate.Height=27;foreach(var h in new[]{"Process","PID","CPU %","RAM MB"})topProcesses.Columns.Add(h,h);topProcesses.Columns[0].FillWeight=180;box.Controls.Add(topProcesses,0,1);table.Controls.Add(box,0,2);
 liveHardware=new Label{Dock=DockStyle.Fill,BackColor=panel,ForeColor=Color.FromArgb(215,226,239),Padding=new Padding(12),Margin=new Padding(0,0,0,12),Font=new Font("Segoe UI",10)};table.Controls.Add(liveHardware,1,2);sensorStrip=new Label{Dock=DockStyle.Fill,BackColor=panel,ForeColor=muted,Padding=new Padding(12),Text="GPU sensors: reading…",Font=new Font("Segoe UI",9)};table.Controls.Add(sensorStrip,0,3);table.SetColumnSpan(sensorStrip,2);
 }
 void UpdateSummary(bool fresh){if(summaryCpu==null||current==null)return;if(fresh){summaryCpu.Add(current.Cpu);summaryRam.Add(current.MemoryPercent);}summaryCpu.Value=Metric(current.Cpu,"%");summaryCpu.Hint=Environment.ProcessorCount+" logical processors · 60 samples";summaryRam.Value=Metric(current.MemoryPercent,"%");summaryRam.Hint=Inventory.Bytes(current.Total-current.Available)+" / "+Inventory.Bytes(current.Total);summaryCpu.Invalidate();summaryRam.Invalidate();
 liveOverview.Text="CPU  "+Metric(current.Cpu,"%")+"       RAM  "+Metric(current.MemoryPercent,"%")+"       PROCESSES  "+current.Processes.Count+"\r\nNETWORK  ↓ "+Inventory.Bytes(current.Receive)+"/s   ↑ "+Inventory.Bytes(current.Send)+"/s       DISK  R "+Inventory.Bytes(current.DiskRead)+"/s   W "+Inventory.Bytes(current.DiskWrite)+"/s";
 topProcesses.Rows.Clear();foreach(var p in current.Processes.OrderByDescending(p=>p.Cpu).Take(6))topProcesses.Rows.Add(p.Name,p.Id,Math.Round(p.Cpu,1),Math.Round(p.Memory/1048576.0,1));topProcesses.ClearSelection();liveHardware.Text="HARDWARE AT A GLANCE\r\n\r\n"+cpuName+"\r\n"+Inventory.Bytes(current.Total)+" usable RAM · "+Inventory.Bytes(current.Available)+" available\r\n"+storageOverview+"\r\n\r\n"+(current.MemoryPercent>=85?"Memory use is above 85%.":"Memory use is below 85%.")+"\r\n"+(current.Cpu>=90?"CPU use is above 90%.":"CPU use is below 90%.");
 sensorStrip.Text=SensorText();sub.Text="Live overview · "+current.Time.ToString("HH:mm:ss")+" · detailed hardware specs in the sidebar";}
 string SensorText(){if(sensors.Count==0)return gpuInfo+"\r\n"+gpuNote;return string.Join("\r\n",sensors.Select(g=>g.Name+"   "+Metric(g.Load,"%")+"   VRAM "+Metric(g.Used/1024," GB")+" / "+Metric(g.Total/1024," GB")+"   "+Metric(g.Temp," °C")+"   "+Metric(g.Power," W")+"   "+Metric(g.Clock," MHz")))+"\r\nNVIDIA sensors · "+sensorTime.ToString("HH:mm:ss")+" · other adapters: GPU specs";}
 List<string[]> GpuRows(){var t=new Table("Component","Specification","Value");AppendSensors(t);t.Rows.AddRange(inventory.Rows);return t.Rows;}
 void AppendSensors(Table t){foreach(var g in sensors){string group="LIVE · NVIDIA GPU "+g.Index+" · "+g.Name;foreach(var row in new[]{new[]{"GPU utilization",Metric(g.Load,"%")},new[]{"Dedicated memory total",Metric(g.Total," MiB")},new[]{"Dedicated memory used",Metric(g.Used," MiB")},new[]{"Temperature",Metric(g.Temp," °C")},new[]{"Board power",Metric(g.Power," W")},new[]{"Power limit",Metric(g.Limit," W")},new[]{"Graphics clock",Metric(g.Clock," MHz")},new[]{"Driver",g.Driver},new[]{"Sampled at",sensorTime.ToString("HH:mm:ss")}})t.Rows.Add(new[]{group,row[0],row[1]});}}
 void ReadStorageOverview(){var worker=new BackgroundWorker();worker.DoWork+=(s,e)=>{var t=Inventory.Hardware("Storage specs");var drives=t.Rows.Where(r=>r[0].StartsWith("Disk ")&&r[1]=="Model").Select(r=>r[2]).ToArray();e.Result=drives.Length==0?"Storage specs unavailable":drives.Length+" physical drive(s)\r\n"+string.Join("\r\n",drives.Take(3));};worker.RunWorkerCompleted+=(s,e)=>{worker.Dispose();if(IsDisposed)return;storageOverview=e.Error==null?(string)e.Result:"Storage specs unavailable";};worker.RunWorkerAsync();}
}
}


